import unittest
from calc import add

class Addition(unittest.TestCase):
    def test_sum(self):
        self.assertEqual(add(2, 3), 5)
        self.assertEqual(add(-2, 3), 1)
        self.assertEqual(add(0, 0), 0)

if __name__ == '__main__':
    unittest.main()

